<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router'
import {Check,Undo2,Trash2,History,Sparkles,Square} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {prepareEditWriting,executeWritingAction,keepEditWriting} from './actions-runtime'
import {slotModel} from '../repositories/local-models'
import {hasPendingWritingSave,retryWritingSave,recoverWriting,stopWriting,writingPendingView} from './runtime'
import type {WritingRun} from './contract'
import {selectionText,type WritingEdit,type TextSelection} from './edits-contract'
import {createWritingEdit,addWritingVariant,saveWritingEditDraft,copyWritingEditDraft,selectWritingVariant,applyWritingVariant} from './edits-runtime'
const props=defineProps<{storyId:string;branchId:string|null;selection:TextSelection|null;open:boolean;sourceRevision?:number;readOnly?:boolean}>(),emit=defineEmits<{close:[]}>(),store=useLocal(),router=useRouter()
const task=ref<Document<WritingRun>|null>(null),requests=ref<Document<WritingRun>[]>([]),writingBusy=ref(false),direction=ref(''),durableDirection=ref('')
const current=ref<Document<WritingEdit>|null>(null),records=ref<Document<WritingEdit>[]>([]),buffer=ref(''),busy=ref(false),error=ref(''),pending=ref(0),hydrating=ref(false),durable=ref('')
const variant=computed(()=>current.value?.value.variants.find(v=>v.id===current.value!.value.selectedVariantId)),labels={source:'原文',manual:'手改',delete:'删除',rewrite:'替换写法',expand:'扩写'},saved=computed(()=>buffer.value===durable.value&&direction.value===durableDirection.value&&pending.value===0)
const currentRequests=computed(()=>requests.value.filter(r=>r.value.purpose&&r.value.purpose.kind!=='directions'&&r.value.purpose.editId===current.value?.id))
let disposed=false,epoch=0,draftWork=Promise.resolve(),opening=new AbortController();const states=new Map<string,{revision:number;durable:string;direction:string}>()
function show(row:Document<WritingEdit>){current.value=row;states.set(row.id,{revision:row.revision,durable:row.value.draftText,direction:row.value.direction});hydrating.value=true;buffer.value=row.value.draftText;durable.value=row.value.draftText;direction.value=row.value.direction;durableDirection.value=row.value.direction;task.value=requests.value.find(r=>r.value.purpose&&r.value.purpose.kind!=='directions'&&r.value.purpose.editId===row.id)||null;hydrating.value=false;const index=records.value.findIndex(r=>r.id===row.id);if(index<0)records.value.unshift(row);else records.value[index]=row}
async function list(){const vault=store.vault;if(!vault)return [];const all=await vault.list<WritingEdit|WritingRun>('settings');requests.value=(all.filter(r=>r.value.assetType==='writing-run'&&(r.value as WritingRun).purpose&&(r.value as WritingRun).purpose!.kind!=='directions'&&(r.value as WritingRun).storyId===props.storyId) as Document<WritingRun>[]).sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));for(let index=0;index<requests.value.length;index++)if(requests.value[index]!.value.status==='running')requests.value[index]=await recoverWriting(vault,requests.value[index]!);const rows=(all as Document<WritingEdit>[]).filter(r=>r.value.assetType==='writing-edit'&&r.value.source.storyId===props.storyId&&(r.value.source.id===(props.branchId||props.storyId)||r.value.targetBranchId===props.branchId));if(disposed||store.vault!==vault)return [];records.value=rows.sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));return records.value}
function saveDraft(){const vault=store.vault,row=current.value,text=buffer.value,requirement=direction.value;if(!vault||!row||hydrating.value||disposed)return draftWork;const state=states.get(row.id)||{revision:row.revision,durable:row.value.draftText,direction:row.value.direction};states.set(row.id,state);pending.value++;const job=draftWork.catch(()=>{}).then(async()=>{if(!vault.unlocked||text===state.durable&&requirement===state.direction)return;const saved=await saveWritingEditDraft(vault,row.id,state.revision,text,requirement);state.direction=requirement;state.revision=saved.revision;state.durable=text;if(!disposed&&store.vault===vault&&current.value?.id===row.id){current.value=saved;durable.value=text;durableDirection.value=requirement}});draftWork=job.finally(()=>pending.value--);void draftWork.catch(e=>{if(!disposed)error.value=(e as Error).message});return draftWork}
watch([buffer,direction],()=>{if(!hydrating.value)void saveDraft()},{flush:'sync'})
watch(()=>props.open,async open=>{opening.abort();const ticket=++epoch;if(!open)return;opening=new AbortController();const signal=opening.signal,vault=store.vault;if(!vault)return;busy.value=true;error.value='';try{await draftWork;const rows=await list();if(disposed||ticket!==epoch||!props.open||store.vault!==vault)return;if(props.selection){const selection=JSON.parse(canonical(props.selection)) as TextSelection,line=await vault.read(props.branchId||props.storyId,props.sourceRevision);if(disposed||ticket!==epoch||!props.open||store.vault!==vault||signal.aborted)return;const prior=rows.find(row=>row.value.source.id===(props.branchId||props.storyId)&&row.value.source.revision===line?.revision&&(props.sourceRevision===undefined?row.value.source.policy!=='forkPinned':row.value.source.policy==='forkPinned')&&canonical(row.value.selection)===canonical(selection)),row=prior||await createWritingEdit(vault,props.storyId,props.branchId,selection,signal,props.sourceRevision);if(!disposed&&ticket===epoch&&props.open&&store.vault===vault)show(row)}else if(rows[0])show(rows[0]);else current.value=null}catch(e){if(!disposed&&ticket===epoch&&!signal.aborted)error.value=(e as Error).message}finally{if(ticket===epoch)busy.value=false}})
async function chooseRecord(id:string){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await saveDraft();await draftWork;const row=await vault.read<WritingEdit>(id);if(!disposed&&row?.value.assetType==='writing-edit')show(row)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function chooseVariant(id:string){const vault=store.vault,row=current.value;if(!vault||!row||busy.value||props.readOnly)return;busy.value=true;try{await saveDraft();await draftWork;show(await selectWritingVariant(vault,row.id,states.get(row.id)!.revision,id));error.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function keep(origin:'manual'|'delete'='manual'){const vault=store.vault,row=current.value;if(!vault||!row||busy.value||props.readOnly)return;busy.value=true;try{await saveDraft();await draftWork;const text=origin==='delete'?'':buffer.value;show(await addWritingVariant(vault,row.id,states.get(row.id)!.revision,{origin,text,raw:text,status:'ready',finishReason:null}));error.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function apply(original=false){const vault=store.vault,row=current.value,ticket=epoch;if(!vault||!row||busy.value||props.readOnly)return;busy.value=true;error.value='';try{await saveDraft();await draftWork;let ready=(await vault.read<WritingEdit>(row.id))!;if(buffer.value!==variant.value?.text)ready=await addWritingVariant(vault,ready.id,ready.revision,{origin:'manual',text:buffer.value,raw:buffer.value,status:'ready',finishReason:null});const chosen=original?ready.value.variants[0]!.id:ready.value.selectedVariantId,result=await applyWritingVariant(vault,ready.id,ready.revision,chosen);if(disposed||ticket!==epoch||!props.open||store.vault!==vault||!vault.unlocked)return;show((await vault.read<WritingEdit>(row.id))!);const branch=await vault.read(result.branchId),edition=(branch!.value as {edition:{paragraphId:string|null}}).edition;emit('close');await router.push({path:'/local/read/'+props.storyId,query:{branch:result.branchId,paragraph:edition.paragraphId||ready.value.selection.start.paragraphId}})}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function generate(mode:'rewrite'|'expand'){
 const vault=store.vault,row=current.value,ticket=epoch;if(!vault||!row||busy.value||writingBusy.value||props.readOnly)return;writingBusy.value=true;error.value=''
 try{await saveDraft();await draftWork;const prepared=await prepareEditWriting(vault,await slotModel(vault,'text'),row.id,states.get(row.id)!.revision,mode,direction.value);requests.value.unshift(prepared);task.value=prepared;const result=await executeWritingAction(vault,prepared.id,value=>{if(!disposed&&current.value?.id===row.id)task.value=writingPendingView(vault,value)});if(hasPendingWritingSave(vault,result.id))return;const candidate=await keepEditWriting(vault,result.id);if(!disposed&&ticket===epoch&&props.open&&store.vault===vault&&current.value?.id===row.id){requests.value[0]=result;show(candidate)}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)writingBusy.value=false}
}
async function keepReceived(){const vault=store.vault,row=task.value;if(!vault||!row||busy.value||writingBusy.value)return;busy.value=true;try{if(hasPendingWritingSave(vault,row.id))task.value=await retryWritingSave(vault,row.id);const candidate=await keepEditWriting(vault,row.id,true);if(!disposed&&store.vault===vault)show(candidate);error.value=''}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function stop(){const vault=store.vault,row=task.value;if(vault&&row)await stopWriting(vault,row.id)}
async function close(){if(busy.value)return;try{await saveDraft();await draftWork;epoch++;emit('close')}catch(e){error.value=(e as Error).message}}
async function copyDraft(){const vault=store.vault,row=current.value;if(!vault||!row||busy.value)return;busy.value=true;try{await draftWork.catch(()=>{});show(await copyWritingEditDraft(vault,row,buffer.value,direction.value));error.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function chooseRequest(id:string){const row=currentRequests.value.find(r=>r.id===id);if(row&&store.vault)task.value=writingPendingView(store.vault,row)}
function beforeUnload(event:BeforeUnloadEvent){if(pending.value||buffer.value!==durable.value||direction.value!==durableDirection.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
async function canLeave(){try{await saveDraft();await draftWork;opening.abort();epoch++;return true}catch(e){error.value=(e as Error).message;return false}}
onBeforeRouteLeave(canLeave)
onBeforeRouteUpdate(canLeave)
onUnmounted(()=>{disposed=true;epoch++;opening.abort();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><Sheet v-if="open" title="编辑正文" @close="close"><div class="final-edit-panel"><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="error&&current&&!saved" :disabled="busy||writingBusy" @click="copyDraft">另存我的输入</button><p v-if="busy&&!current" role="status">正在打开选区…</p><template v-if="current"><fieldset :disabled="busy||writingBusy||readOnly"><small v-if="readOnly" role="status">已归档 · 只读</small><small v-else-if="current.value.source.policy==='forkPinned'" role="status">从历史 v{{current.value.source.revision}} 另开故事线</small><details class="final-edit-source"><summary>原文选区</summary><blockquote>{{selectionText(current.value.selection,current.value.paragraphs)}}</blockquote></details><label>写法<select aria-label="选择编辑候选" :value="current.value.selectedVariantId" @change="chooseVariant(($event.target as HTMLSelectElement).value)"><option v-for="(candidate,index) in current.value.variants" :key="candidate.id" :value="candidate.id">{{labels[candidate.origin]}} · {{index+1}}{{candidate.status==='partial'?' · 未完成片段':''}}{{candidate.id===current.value.appliedVariantId?' · 当前正文':''}}</option></select></label><label>正文<textarea v-model="buffer" aria-label="编辑选区正文" maxlength="1000000" rows="9"/></label><small role="status">{{saved?'草稿已保存':'正在保存草稿…'}}</small><label>改写要求 <small>选填</small><textarea v-model="direction" aria-label="改写要求" maxlength="20000" rows="2"/></label><div class="final-grid-actions"><button @click="generate('expand')"><Sparkles :size="16"/>扩写</button><button @click="generate('rewrite')"><Sparkles :size="16"/>替换写法</button><RouterLink class="final-text-link" to="/local/settings/models">模型</RouterLink></div><div class="final-grid-actions"><button @click="keep()">{{variant?.status==='partial'?'另存为手改候选':'保存候选'}}</button><button @click="keep('delete')"><Trash2 :size="16"/>删除选区</button></div><div class="final-edit-primary"><button v-if="current.value.appliedRevision" @click="apply(true)"><Undo2 :size="16"/>恢复原文</button><button class="final-primary" :disabled="variant?.status==='partial'" @click="apply()"><Check :size="16"/>应用并阅读</button></div></fieldset><label v-if="currentRequests.length">生成记录<select aria-label="选择选区生成记录" :value="task?.id" :disabled="writingBusy" @change="chooseRequest(($event.target as HTMLSelectElement).value)"><option v-for="row in currentRequests" :key="row.id" :value="row.id">{{new Date(row.value.createdAt).toLocaleString()}} · {{row.value.purpose?.kind==='expand'?'扩写':'替换写法'}} · {{row.value.status==='completed'?'已完成':row.value.status==='running'?'正在写':'未完成'}}</option></select></label><article v-if="task" class="final-edit-generated" aria-label="生成写法"><div class="final-edit-primary"><span>{{task.value.status==='running'?'正在写…':'生成记录'}}</span><button v-if="['queued','running'].includes(task.value.status)" @click="stop"><Square :size="15"/>停止</button></div><p class="final-edit-stream">{{task.value.chapters[0]?.text||'等待可读正文…'}}</p><p v-if="task.value.error" class="final-error">{{task.value.error}}</p><button v-if="store.vault&&hasPendingWritingSave(store.vault,task.id)" :disabled="busy" @click="keepReceived">只重试保存</button><button v-else-if="!['queued','running'].includes(task.value.status)&&task.value.chapters[0]?.text&&!current.value.variants.some(v=>v.runId===task!.id)" :disabled="busy" @click="keepReceived">保存收到的候选</button><details v-if="task.value.chapters[0]?.raw"><summary>原返回</summary><pre>{{task.value.chapters[0]?.raw}}</pre></details></article></template><p v-else-if="!busy" class="final-subtle">暂无编辑记录</p><details v-if="records.length" class="final-edit-history"><summary><History :size="16"/>编辑记录</summary><button v-for="row in records" :key="row.id" :disabled="busy" @click="chooseRecord(row.id)">{{new Date(row.value.createdAt).toLocaleString()}} · {{row.value.variants.length}} 个写法</button></details></div></Sheet></template>
<style scoped>
.final-edit-panel{display:grid;gap:20px}.final-edit-panel fieldset{border:0;padding:0;margin:0;display:grid;gap:18px;min-width:0}.final-edit-panel label{display:grid;gap:9px}.final-edit-panel textarea{font:18px/1.8 var(--font-reading,serif);resize:vertical}.final-edit-source blockquote{margin:14px 0 0;border-left:2px solid var(--accent);padding:12px 16px;background:var(--wash);white-space:pre-wrap;font:17px/1.8 serif}.final-edit-panel small{color:var(--quiet);font-size:12px}.final-edit-generated{border-top:1px solid var(--edge);padding-top:18px;display:grid;gap:12px}.final-edit-stream,.final-edit-generated pre{white-space:pre-wrap;overflow-wrap:anywhere;font:17px/1.8 serif}.final-edit-generated pre{max-height:40dvh;overflow:auto}.final-edit-primary{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:18px;border-top:1px solid var(--edge)}.final-edit-primary>.final-primary{margin-left:auto}.final-edit-history summary{display:flex;gap:8px;align-items:center;cursor:pointer}.final-edit-history button{display:block;width:100%;margin-top:10px;text-align:left}@media(prefers-reduced-motion:no-preference){.final-edit-panel{animation:edit-in .2s ease-out}@keyframes edit-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}}
</style>
